select COUNT(1) as count from ( select cn.*,cnr.id as rid from cms_notice cn LEFT JOIN cms_notice_read cnr on cnr.notice_id = cn.id where 1 = 1
and if_public = 1
and ( cn.role_code = #{roleCode})
and cn.type = #{type}
and ( cn.user_id = #{userId})
) aa where rid is null

select aa.* from ( select cn.*,cnr.id as rid from cms_notice cn LEFT JOIN cms_notice_read cnr on cnr.notice_id = cn.id where 1 = 1
and ( cn.user_id = #{userId} or if_public =1)
) aa where rid is null
